package com.fakelegacy.order.web;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.repo.OrderRepository;
import com.fakelegacy.order.service.OrderManager;
import com.fakelegacy.order.service.ReturnService;
import com.fakelegacy.order.web.ApiRequests.ReturnRequest;

@RestController
public class ReturnController {

    private static final int RETURN_WINDOW_DAYS = 14;

    @Autowired
    private OrderRepository orders;
    @Autowired
    private ReturnService returnService;
    @Autowired
    private OrderManager orderManager;

    // O9
    @PostMapping("/orders/{id}/return")
    public ResponseEntity<Object> returnItems(@PathVariable("id") Long id, @RequestBody ReturnRequest req) {
        Order order = orders.findById(id).orElse(null);
        if (order == null) {
            return ResponseEntity.notFound().build();
        }
        if (!"DELIVERED".equals(order.getStatus())) {
            return refuse("only delivered orders can be returned (current status: " + order.getStatus() + ")");
        }
        if (LocalDateTime.now().isAfter(order.getDeliveredAt().plusDays(RETURN_WINDOW_DAYS))) {
            return refuse("the " + RETURN_WINDOW_DAYS + "-day return window is over");
        }
        Map<String, Integer> items = returnService.validate(order, req.items());
        return ResponseEntity.ok(orderManager.processReturn(order, items));
    }

    private ResponseEntity<Object> refuse(String text) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("message", text);
        return ResponseEntity.badRequest().body(m);
    }
}
